function tran(a, b) {
    let t;
    let res = 0;
    let pow = 1;
    do {
        t = Math.floor(a / b);
        res += pow * (a % b);
        a = t;
        pow *= 10;
    } while (t >= b);
    res += pow * t;
    return res;
}

const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim();
const b = parseInt(input, 10);
let output = '';
for (let i = 1; i < b; i++) {
    for (let j = 1; j < b; j++) {
        output += tran(i * j, b) + ' ';
    }
    output += '\n';
}
console.log(output);

