function tran(a, b) {
    let t;
    let res = 0;
    let pow = 1;
    do {
        t = Math.floor(a / b);
        res += pow * (a - Math.floor(a / b) * b);
        a = t;
        pow *= 10;
    } while (t >= b);
    res += pow * t;
    return res;
}

