    const input = fs.readFileSync(0, 'utf-8').trim();
    const b = parseInt(input, 10);
    let output = '';
    for (let i = 1; i < b; i++) {
        for (let j = 1; j < b; j++) {
            output += tran(i * j, b) + ' ';
        }
        output += '\n';
    }
    console.log(output);
}

